criteria.get_position_card:
name: get_position_card
title: Получить карточку роли
kind: recipe
version: 1.0.0
status: active
domain: position
description: >
  Получить полную справочную карточку штатной должности по её position_id:
  оргструктура, грейд, эталон, типовая должность, регион, признак вакансии. Когда
  нужна карточка конкретной должности по её ID.
tags: [должность, роль, карточка, position_id, оргструктура, грейд, вакансия]
purpose: Полная справка о должности по её position_id.
model:
  schema: dm_core
  logic_model: position_actual
  table: dm_core.position_actual
rest_equivalent: true
params:
  - name: position_id
    target: position_id
    substitutes: value
    required: true
    description: ID штатной должности, передавай строкой.
query:
  schema: dm_core
  logic_model: position_actual
  columns: [position_id, position_name, position_name_long, company, pos_grade_num, grade_rank, flag_boss, vacancy_clear_flag, vacancy_start_date, oshs.fblock_code, oshs.fblock_name, oshs.unit_name_tree, et_pos_id, et_pos_name, type_position_id, type_position_name, professionlevel_id, professionlevel_name, team_role, expertise_area, segment_name, region_name, city_name, end_date, segment]
  filters:
    type: condition
    column: position_id
    operator: "="
    value: "12345"
  limit: 1
output:
  - {field: position_id, title: ID штатной должности}
  - {field: position_name, title: Среднее наименование должности}
  - {field: position_name_long, title: Длинное наименование должности}
  - {field: company, title: Компания}
  - {field: pos_grade_num, title: Грейд (числовой)}
  - {field: grade_rank, title: Разряд (полный)}
  - {field: flag_boss, title: Флаг руководящей ШД}
  - {field: vacancy_clear_flag, title: Флаг «Чистая вакансия»}
  - {field: vacancy_start_date, title: Дата возникновения вакансии}
  - {field: oshs.fblock_code, title: Код функционального блока по ОШС (линейная структура)}
  - {field: oshs.fblock_name, title: Наименование функционального блока по ОШС (линейная структура)}
  - {field: oshs.unit_name_tree, title: Дерево названий подразделений по ОШС (линейная структура)}
  - {field: et_pos_id, title: ID эталонной должности}
  - {field: et_pos_name, title: Наименование эталонной должности}
  - {field: type_position_id, title: ID типовой должности}
  - {field: type_position_name, title: Наименование типовой должности}
  - {field: professionlevel_id, title: ID типового профиля должности}
  - {field: professionlevel_name, title: Наименование типового профиля должности}
  - {field: team_role, title: Роль команды}
  - {field: expertise_area, title: Область экспертизы}
  - {field: segment_name, title: Наименование сегмента}
  - {field: region_name, title: Наименование региона}
  - {field: city_name, title: Наименование города}
  - {field: end_date, title: Дата вывода ШД}
  - {field: segment, title: Сегмент (включая ТОП-600)}
related:
  - {name: find_position_by_name, relation: prerequisite, note: найти должность по названию и взять position_id}
  - {name: find_position_by_name_top600, relation: prerequisite, note: найти должность ТОП-600 по названию и взять position_id}
  - {name: get_position_holder, relation: follow_up, note: кто сейчас занимает должность}
notes:
  - Меняется только position_id, это идентификатор штатной должности, передавай строкой.
  - position_id уникален, поэтому limit равен 1, вернётся одна строка или пусто.
  - Поля oshs.* это Nested-подполя линейной структуры.
  - Это справочник должностей, не сотрудники.

